{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Tofacitinib, which shares the N-methylpyrrolopyrimidine amine with the query, has an absolute oral bioavailability of 74% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Baricitinib, a sulfonamide-containing pyrrolopyrimidine JAK inhibitor structurally related to the query, has an absolute oral bioavailability of 80% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ruxolitinib, another pyrrolopyrimidine-based JAK inhibitor, has an absolute oral bioavailability of 74% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Upadacitinib, a related JAK inhibitor, is reported to have sufficiently high oral bioavailability for oral administration in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Sumatriptan, a sulfonamide-containing drug, has low oral bioavailability (14%) in humans, but its indole/triptan scaffold is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pyrrolopyrimidine JAK-inhibitor-like molecule with a sulfonamide and cyclobutane core. High-transfer evidence from tofacitinib (74% F), baricitinib (80% F), ruxolitinib (74% F), and upadacitinib (high F) consistently supports high oral bioavailability. The only low-F evidence (sumatriptan, 14%) is structurally distant and does not outweigh the class-consistent high-F data. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability value is available for the exact query molecule.",
    "Analog similarities are moderate (Morgan scores roughly 0.20-0.42), so transfer relies on structural class analogy rather than near-neighbor identity.",
    "First-pass metabolism and absorption characteristics of the specific propylsulfonamide cyclobutane moiety are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

